import{_ as t}from"./chunks/vision_tasks.BzIM5FUo.js";import{_ as o,o as s,c as r,a0 as i}from"./chunks/framework.Ckbw5VQO.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/models/introduction.md","filePath":"fr/guide/models/introduction.md"}'),n={name:"fr/guide/models/introduction.md"};function a(l,e,d,c,u,p){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>On peut détecter beaucoup de choses sur une orthophoto, mais toutes ne se valent pas en difficulté. Deux facteurs décident de la faisabilité : la <strong>disponibilité de labels</strong> prêts à l&#39;emploi et la <strong>forme</strong> de l&#39;objet.</p><ul><li>🟢 <code>Piscines</code> : couleur unique, forme simple, peu de faux positifs</li><li>🟢 <code>Bâtiments</code> : labels gratuits <a href="https://geoservices.ign.fr/bdtopo" target="_blank" rel="noreferrer">BD TOPO</a></li><li>🟡 <code>Forêts</code> : labels BD Forêt IGN, mais fusion de polygones complexe</li><li>🟠 <code>Arbres isolés</code> : zoom élevé requis, instances difficiles à séparer</li><li>🔴 <code>Routes</code> : fines, longues, occultées par les arbres</li></ul><div class="tip custom-block"><p class="custom-block-title">Le choix de ce projet</p><p><strong>piscines</strong> &amp; <strong>bâtiments</strong> : formes simples et labels disponibles gratuitement (<a href="https://www.openstreetmap.org/" target="_blank" rel="noreferrer">OpenStreetMap</a> pour les piscines, <a href="https://geoservices.ign.fr/bdtopo" target="_blank" rel="noreferrer">BD TOPO</a> pour les bâtiments).</p></div><h2 id="les-trois-taches-de-computer-vision" tabindex="-1">Les trois tâches de computer vision <a class="header-anchor" href="#les-trois-taches-de-computer-vision" aria-label="Permalink to &quot;Les trois tâches de computer vision&quot;">​</a></h2><p>Face à une image, un modèle peut répondre à trois questions de plus en plus précises.</p><img src="'+t+'" style="display:block;margin:0 auto;width:100%;height:auto;"><table tabindex="0"><thead><tr><th>Tâche</th><th>Question</th><th>Sortie</th><th>Modèles</th></tr></thead><tbody><tr><td><strong>Classification</strong></td><td>Qu&#39;y a-t-il dans l&#39;image ?</td><td>Une seule réponse pour toute l&#39;image (« c&#39;est une forêt - 94 % »)</td><td>CNN classique</td></tr><tr><td><strong>Détection d&#39;objets</strong></td><td>Où sont les objets, et combien ?</td><td>Une boîte englobante (<em>bounding box</em>) autour de chaque objet, avec un score de confiance</td><td>YOLO, Faster R-CNN, SSD</td></tr><tr><td><strong>Segmentation</strong></td><td>À quelle classe appartient chaque pixel ?</td><td>Une classe attribuée à chaque pixel (« ce pixel = bâtiment, celui-là = eau »)</td><td>U-Net, SegFormer</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Choix : détection avec <a href="https://docs.ultralytics.com/models/yolov8/" target="_blank" rel="noreferrer">YOLOv8</a></p><p>La détection est <strong>plus légère</strong>, <strong>plus rapide à entraîner</strong>, <strong>plus fiable à exporter en ONNX</strong> pour tourner côté client.</p></div>',9)])])}const b=o(n,[["render",a]]);export{h as __pageData,b as default};
